class Solution {
public:
    int subarrayGCD(std::vector<int>& nums, int k) {
        int n = nums.size();
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int cur_gcd = 0;
            for (int j = i; j < n; j++) {
                cur_gcd = std::gcd(cur_gcd, nums[j]);
                if (cur_gcd == k) {
                    ans++;
                } else if (cur_gcd % k != 0) {
                    break;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int subarrayGCD(int[] nums, int k) {
        int n = nums.length;
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int curGcd = 0;
            for (int j = i; j < n; j++) {
                curGcd = gcd(curGcd, nums[j]);
                if (curGcd == k) {
                    ans++;
                } else if (curGcd % k != 0) {
                    break;
                }
            }
        }
        return ans;
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

